'use strict';
const KEY='suilven-web-v1', app=document.querySelector('#app');
const seed={version:1,jobs:[],parts:[{id:'oil',name:'Main engine oil filter',number:'RE504836',quantity:null,location:'',minimum:1}],service:{lastHours:2979,lastDate:'2026-02-27',interval:250},completions:[],passages:[],checks:[],manuals:[]};
let state,blocked=false,page='home',selectedPart='oil',selectedTask='',search='',partsReturnPage='parts',partsScroll=0,partSaved=false;
try{state=JSON.parse(localStorage.getItem(KEY)||'null')||structuredClone(seed);validate(state)}catch(e){state=structuredClone(seed);blocked=true}
function validate(s){if(s.version!==1||!['jobs','parts','completions','passages','checks','manuals'].every(k=>Array.isArray(s[k]))||!s.service||!Number.isFinite(s.service.lastHours)||s.service.interval<=0)throw Error('Unrecognised backup');for(const p of s.parts)if(p.quantity!==null&&(!Number.isFinite(p.quantity)||p.quantity<0))throw Error('Invalid stock')}
function migrate(d){d.tasks??=[];d.scheduleDrafts??=[];d.boatServiceLibrary??={tasks:[],sections:[]};for(const p of d.parts){p.supplier??="";p.aliases??="";p.category??="Engine";p.verified??=p.quantity!==null}return d}
state=migrate(state);
function commit(fn){if(blocked)throw Error('Existing records could not be read. Export recovery data before restoring a valid backup.');const next=migrate(structuredClone(state));fn(next);validate(next);localStorage.setItem(KEY,JSON.stringify(next));state=next}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function msg(t){document.querySelector('#message').textContent=t;const feedback=document.querySelector('#stock-feedback');if(feedback){feedback.textContent=t;feedback.className=t?'save-confirmation':'';if(t)feedback.scrollIntoView({block:'nearest'})}}
function field(name,label,type='text',value=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'step="any" min="0"':''} required></label>`}
function download(name,content,type='application/json'){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000)}
function num(f,k){const n=Number(f.get(k));if(f.get(k)===''||!Number.isFinite(n)||n<0)throw Error('Enter valid non-negative numbers');return n}
function render(){msg('');renderEngineHours();if(page==='home'){app.innerHTML=`<h1>Your boat. Everything in reach.</h1><p class="muted">Offline-first boat manager. Last recorded engine hours are shown above.</p>${blocked?'<p class="warning">Storage could not be read. Saving is blocked to protect the original.</p>':''}<div class="grid">${[['service','Servicing'],['parts','Parts & Spares'],['jobs','Problems & Jobs'],['fuel','Passages & Fuel'],['checks','Pre-departure Checks'],['manuals','Manuals & Boat Information'],['report','Vessel Report'],['backup','Backup & Restore']].map(([id,n])=>`<button class="tile" data-page="${id}">${n}</button>`).join('')}</div><p class="warning">Historical inventory can now be imported locally. Full manual schedules still need review.</p>`}
if(page==='jobs'){app.innerHTML=`<h1>Problems & Jobs</h1><form id="job">${field('title','Problem or job')}<label>Notes<textarea name="notes"></textarea></label><label>Equipment<select name="equipment">${['Main engine','Wing engine','Generator','Other equipment'].map(e=>`<option>${e}</option>`).join('')}</select></label><button class="primary">Add job</button></form>${state.jobs.map(j=>`<article><h2>${esc(j.title)}</h2><p>${esc(j.notes)}</p><p class="muted">${esc(j.equipment)} · ${esc(j.date)}</p><button data-status="${j.id}">${esc(j.status)} — change status</button></article>`).join('')}`}
if(page==='parts'){const matches=state.parts.filter(p=>[p.name,p.number,p.aliases,p.category,p.location,p.historicalLocation].join(' ').toLowerCase().includes(search.toLowerCase()));app.innerHTML=`<h1>Parts & Spares</h1>${partSaved?'<p class="save-confirmation" role="status">✓ Part saved on this device.</p>':''}<div class="row"><button data-page="inventory-import">Import historical inventory</button><button data-newpart>Add a part</button><button data-page="reorder">Reorder list</button></div><label>Search name, part number, supplier alias or location<input id="part-search" value="${esc(search)}" placeholder="e.g. impeller, RE504836 or generator"></label><p>${state.parts.length} catalogue entries · ${state.parts.filter(p=>p.verified).length} counted and confirmed</p>${matches.map(p=>`<article><h2>${esc(p.name)}</h2><p>${esc(p.number)} · ${esc(p.category)}</p><p>${p.verified?`${p.quantity} onboard · ${esc(p.location)}`:'Current quantity and location need checking'}</p>${p.verified&&p.quantity<=p.minimum?'<p class="warning">Reorder — at or below threshold</p>':''}<button data-part="${esc(p.id)}">View / confirm stock</button></article>`).join('')}`}
if(page==='part'){const p=state.parts.find(p=>p.id===selectedPart);app.innerHTML=`<h1>Part details</h1><button type="button" data-partsback>← Back to spares list</button>${partSaved?'<p class="save-confirmation" role="status">✓ Changes saved on this device.</p>':''}<p id="stock-feedback" role="status"></p>${partReferences(p)}<form id="stock" novalidate>${field('name','Part name','text',p.name)}${field('number','Part number','text',p.number)}${field('category','Equipment / category','text',p.category)}<fieldset><legend>Used by equipment · select all that apply</legend>${equipmentNames.map(n=>`<label><input type="checkbox" name="equipmentGroups" value="${n}" ${partGroups(p).includes(n)?'checked':''}>${n}</label>`).join('')}</fieldset><p class="warning">Historical record: ${esc(p.historicalQuantity??'not recorded')} · ${esc(p.historicalLocation??'not recorded')}. Check against the part label; imported numbers are unverified.</p><p class="muted">${esc(p.source??'Owner-entered record')}</p>${field('quantity','Counted quantity onboard','number',p.quantity??'')}${field('location','Current storage location','text',p.location)}${field('minimum','Reorder when stock reaches','number',p.minimum)}<label>Supplier / last purchase<input name="supplier" value="${esc(p.supplier)}"></label><label>Alternative supplier part numbers / fit notes<textarea name="aliases">${esc(p.aliases)}</textarea></label><p>Alternative numbers are notes, not verified interchangeable parts.</p><button class="primary" name="action" value="return">Save & return to list</button><button name="action" value="stay">Save & stay here</button></form>`}
if(page==='inventory-import'){app.innerHTML=`<h1>Import your inventory</h1><section><p>Select the Suilven historical inventory JSON file supplied separately. It is read locally; nothing is uploaded to GitHub.</p><p>Existing matched part numbers keep their current stock and location. Separate historical entries stay separate; repeated import IDs are skipped. Every newly imported item starts with unconfirmed current stock.</p><input id="inventory-file" type="file" accept=".json,application/json"></section>`}
if(page==='reorder'){const parts=state.parts.filter(p=>p.verified&&p.quantity<=p.minimum);app.innerHTML=`<h1>Reorder list</h1>${parts.length?parts.map(p=>`<article><h2>${esc(p.name)}</h2><p>${esc(p.number)} · ${p.quantity} onboard · threshold ${p.minimum}</p><p>${esc(p.supplier)}</p><button data-part="${esc(p.id)}">View part</button></article>`).join(''):'<p>No confirmed parts are at or below their threshold.</p>'}<p>Uncounted inventory is excluded; check it before ordering.</p>`}
if(page==='boat-services'){app.innerHTML=`<h1>Whole-boat service library</h1><p>Import the supplied reference library once. Your PDFs stay local. Existing active schedules and service history are preserved.</p><form id="boat-service-import"><label>Select the service library from Files<input id="boat-service-file" name="library" type="file" accept=".json,application/json" required></label><button class="primary" type="submit">Import selected library</button></form><p id="boat-import-status" role="status"></p><p><strong>${state.boatServiceLibrary.tasks.length} service references saved on this device.</strong></p><p>${esc(state.boatServiceLibrary.notes??'Reference library not yet imported.')}</p><label>Find a task<input id="boat-task-search" type="search" placeholder="Windlass, anode, filter…"></label><div class="grid">${[...new Set([...state.boatServiceLibrary.sections.map(s=>s.equipment),...state.boatServiceLibrary.tasks.map(t=>t.equipment)])].sort().map(e=>`<button class="tile" data-boat-equipment="${esc(e)}">${esc(e)}</button>`).join('')}</div><div id="boat-task-results"></div>`}
if(page==='boat-equipment'){const e=boatEquipment,section=state.boatServiceLibrary.sections.find(s=>s.equipment===e);app.innerHTML=`<h1>${esc(e)}</h1><button data-page="boat-services">← All equipment</button>${section?libraryReferenceLinks(section.references):''}${state.boatServiceLibrary.tasks.filter(t=>t.equipment===e).map(boatTaskCard).join('')}`}
if(page==='boat-task'){const t=state.boatServiceLibrary.tasks.find(t=>t.id===boatTaskID),active=state.tasks.find(a=>a.importID===t.id);app.innerHTML=`<h1>${esc(t.equipment)} · ${esc(t.name)}</h1><button data-boat-equipment="${esc(t.equipment)}">← Equipment tasks</button><button data-page="attention">Needs attention</button>${active?scheduleStatusHTML(active):''}<p><strong>Trigger:</strong> ${esc(t.trigger||t.intervalBasis)}</p><p>${esc(t.reviewNotes)}</p>${libraryReferenceLinks(t.references)}<p>These references do not confirm the task has been completed.</p>${t.id==='n43-main-oil-confirmed'?'<button data-page="main">Open existing oil & filter service record</button>':active?`<button data-task="${esc(active.id)}">Record service</button>`:(t.intervalHours||t.intervalMonths)?`<button data-draft="${esc(t.id)}">Review / activate schedule</button>`:'<p>This is an event or condition-based task. Use Record inspection when it has actually been carried out.</p>'}<form id="boat-inspection" data-id="${esc(t.id)}">${field('date','Date actually completed','date',new Date().toISOString().slice(0,10))}<label>Work / inspection notes<textarea name="notes" required></textarea></label><button>Record inspection · no stock deduction</button></form>${state.completions.filter(c=>c.libraryID===t.id).slice().reverse().map(c=>`<article><p>${esc(c.date)} · ${esc(c.notes)}</p></article>`).join('')}`}
if(page==='schedule-import'){app.innerHTML=`<h1>Schedule review list</h1>${reviewNotice?`<p class="save-confirmation" role="status">${esc(reviewNotice)}</p>`:''}<p>Import the supplied schedule file locally. Review each reference, interval and last-service baseline before activating it. Existing schedules and the confirmed main-engine oil record are preserved.</p><p>This first library covers core recurring service tasks. Daily checks, commissioning and specialist injector / pump requirements still need separate review.</p><input id="schedule-file" type="file" accept=".json,application/json"><p>${state.scheduleDrafts.filter(d=>!d.activated).length} schedules awaiting review</p>${state.scheduleDrafts.filter(d=>!d.activated).map(d=>`<article><h2>${esc(d.equipment)} · ${esc(d.name)}</h2><p>${esc(d.source)}</p><p>${esc(d.reviewNotes)}</p><button data-draft="${esc(d.id)}">Review & activate</button></article>`).join('')}`}
if(page==='schedule-review'){const d=state.scheduleDrafts.find(d=>d.id===selectedTask);app.innerHTML=`<h1>${esc(d.equipment)} · ${esc(d.name)}</h1><button type="button" data-reviewback>← Back to review list</button><p>${esc(d.source)}</p><p class="warning">${esc(d.reviewNotes)}</p><p>Suggested interval: ${d.intervalHours??'—'} hours / ${d.intervalMonths??'—'} months. ${esc(d.intervalBasis)}</p><p>Historical baseline: ${d.lastHours??'No meter recorded'} hours · ${esc(d.lastDate??'Date unknown')}. ${esc(d.baselineSource)}</p><form id="activate-schedule"><label>Chosen hour interval<input name="intervalHours" type="number" min="0" step="any" value="${d.intervalHours??''}"></label><label>Chosen month interval<input name="intervalMonths" type="number" min="0" step="1" value="${d.intervalMonths??''}"></label><label>Last completed hours<input name="lastHours" type="number" min="0" step="any" value="${d.lastHours??''}"></label><label>Last completed date<input name="lastDate" type="date" value="${esc(d.lastDate??'')}"></label>${field('basis','Reason for chosen interval / confirmation notes','text',d.intervalBasis)}${partPicker(d.equipment)}<p>Choose a part only after checking its fit. No supplier equivalents are assumed.</p><label><input name="confirmed" type="checkbox" required> I have checked applicability to the fitted equipment, the interval and the baseline.</label><button class="primary">Activate schedule</button></form>`}
if(page==='upcoming'){app.innerHTML=upcomingMaintenance()}
if(page==='attention'){app.innerHTML=servicingAttention()}
if(page==='service'){app.innerHTML=servicingHome()}

if(page==='tasks'){app.innerHTML=`<h1>${esc(selectedTask)} · Servicing</h1><button data-page="newtask">Add a schedule</button>${state.tasks.filter(t=>t.equipment===selectedTask).map(t=>`<article><h2>${esc(t.name)}</h2>${scheduleStatusHTML(t)}<p>${esc(t.source)}</p><p>${t.lastHours!==null&&t.intervalHours?`Next at ${t.lastHours+t.intervalHours} hours`:(t.intervalHours?'Last-service hours unknown':'No hour interval')} · ${t.lastDate&&t.intervalMonths?`Next date ${nextDate(t.lastDate,t.intervalMonths)}`:(t.intervalMonths?'Last-service date unknown':'No calendar interval')}</p><button data-task="${t.id}">Record service</button></article>`).join('')}`}
if(page==='newtask'){app.innerHTML=`<h1>Add ${esc(selectedTask)} schedule</h1><form id="newtask">${field('name','Task name')}<label>Interval · engine hours (optional)<input name="intervalHours" type="number" step="any" min="0"></label><label>Interval · months (optional)<input name="intervalMonths" type="number" step="1" min="0"></label><label>Last completed engine hours (optional)<input name="lastHours" type="number" step="any" min="0"></label><label>Last completed date (optional)<input name="lastDate" type="date"></label>${field('source','Manual reference / owner preference')}${partPicker(selectedTask)}<button class="primary">Save schedule</button></form>`}
if(page==='task'){const t=state.tasks.find(t=>t.id===selectedTask);app.innerHTML=`<h1>${esc(t.name)}</h1><button data-page="attention">← Needs attention</button><button data-page="upcoming">Upcoming maintenance</button><p>${esc(t.equipment)} · ${esc(t.source)}</p>${scheduleStatusHTML(t)}${serviceReferences(t)}<form id="task-service">${field('date','Completed date','date',new Date().toISOString().slice(0,10))}<label>Equipment hours (optional)<input name="hours" type="number" step="any" min="0"></label>${field('used','Quantity used from linked part','number',t.part?1:0)}${partPicker(t.equipment,t.part)}<label>Work notes<textarea name="notes"></textarea></label><button class="primary">Record service & deduct stock</button></form>${state.completions.filter(c=>c.taskID===t.id).slice().reverse().map(c=>`<article>${esc(c.date)} · ${c.hours??'No meter'} hours<p>${esc(c.notes)}</p>${c.reversed?'Reversed':`<button data-taskundo="${c.id}">Undo completion</button>`}</article>`).join('')}`}

if(page==='main'){const t=state.service;app.innerHTML=`<h1>Main engine · Oil & filter</h1><button data-page="attention">← Needs attention</button><button data-page="upcoming">Upcoming maintenance</button>${scheduleStatusHTML({equipment:'Main engine',intervalHours:t.interval,lastHours:t.lastHours,lastDate:t.lastDate})}${serviceReferences({equipment:'Main engine',name:'Oil and filter',importID:'main-oil'})}<section><p>Last recorded: ${t.lastHours} hours · ${esc(t.lastDate)}</p><h2>Next due: ${t.lastHours+t.interval} hours</h2><p>Owner interval: 250 hours. Oil: John Deere Plus 50, 15W-40. Calendar interval awaiting confirmation.</p></section><form id="service">${field('date','Completion date','date',new Date().toISOString().slice(0,10))}${field('hours','Engine hours','number')}${field('used','Oil filters actually used','number',1)}<label>Work notes<textarea name="notes"></textarea></label><button class="primary">Save service & deduct stock</button></form>${state.completions.filter(c=>!c.taskID&&!c.libraryID).slice().reverse().map(c=>`<article>${esc(c.date)} · ${c.hours} h · ${c.used} filter(s)<p>${esc(c.notes)}</p>${c.reversed?'Reversed':'<button data-undo="'+c.id+'">Undo completion</button>'}</article>`).join('')}`}
if(page==='fuel'){app.innerHTML=`<h1>Passages & Fuel</h1><p>Main tanks supply the main engine and generator. Wing engine tank is separate. Quantities below are total US gallons across the main tanks.</p><form id="fuel">${field('name','Passage name')}${['start','end','added','distance','duration'].map((k,i)=>field(k,['Starting fuel · US gal','Finishing fuel · US gal','Fuel added · US gal','Distance · NM','Duration · hours'][i],'number',k==='added'?0:'')).join('')}<button class="primary">Calculate & save</button></form>${state.passages.slice().reverse().map(p=>`<article><h2>${esc(p.name)}</h2><p>${p.litres.toFixed(1)} litres total used · ${(p.litres/p.duration).toFixed(2)} L/h · ${(p.litres/p.distance).toFixed(2)} L/NM</p><p>Average speed ${(p.distance/p.duration).toFixed(1)} knots. Combined main engine + generator consumption.</p></article>`).join('')}`}
if(page==='checks'){app.innerHTML=`<h1>Pre-departure Checks</h1><p class="warning">Starter checklist. Review against the boat manual before use.</p><button id="fresh">Start a fresh checklist</button>${state.checks.length?`<section><p>${esc(state.checks.at(-1).date)}</p>${state.checks.at(-1).items.map((c,i)=>`<label>${esc(c.title)}<select data-check="${i}">${['Unchecked','Checked','Needs attention','Not applicable'].map(v=>`<option ${c.status===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}</section>`:''}<p>${state.checks.length} dated checklists retained.</p>`}
if(page==='manuals'){app.innerHTML=`<h1>Manuals & Boat Information</h1><p>PDF copies stay in this browser on this iPad. Keep originals in Files. JSON backups include catalogue entries only, not PDF files.</p><form id="manual-import"><label>Equipment<select name="equipment"><option>Automatic from filename</option>${equipmentNames.map(n=>`<option>${n}</option>`).join('')}</select></label><label>Select PDFs from Files<input name="files" type="file" accept=".pdf,application/pdf" multiple required></label><button class="primary">Save selected manuals offline</button></form><p id="manual-status" role="status"></p><button id="manual-storage">Check storage / request retention</button><p id="manual-storage-status"></p>${manualLibrary()}`}
if(page==='report'){app.innerHTML=`<div class="report-controls"><h1>Vessel Report</h1><button id="print-report" class="primary">Print / save as PDF</button><button id="download-report">Download readable report</button><p>On iPad, use the print preview / share options to save the PDF to Files. The readable HTML export opens offline in a browser.</p></div>${vesselReport()}`}
if(page==='backup'){app.innerHTML=`<h1>Backup & Restore</h1><section><p>Export saves your local records as a JSON file. Keep it in Files on your iPad. Restore replaces this browser's current records after confirmation.</p><button id="export">Export backup</button><label>Restore a backup<input id="restore" type="file" accept=".json,application/json"></label><p>Native Swift backups and browser backups use different formats. This build does not import Swift records.</p></section>`}
}
document.querySelector('#home').onclick=()=>{page='home';render()};
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.page){page=b.dataset.page;render()}if(b.hasAttribute('data-pending'))msg('Schedule pending manual review');if(b.dataset.status){commit(s=>{const j=s.jobs.find(j=>j.id===b.dataset.status);j.status=({'Open':'In progress','In progress':'Completed','Completed':'Open'})[j.status]});render()}if(b.id==='fresh'){commit(s=>s.checks.push({date:new Date().toISOString(),items:['Engine oil and coolant','Leaks, belts and strainers','Seacock positions','Main and wing fuel','Shore power disconnected','Weather, tides and passage plan','Radios and navigation equipment','Crew briefing and safety equipment','Tender, hatches and loose gear'].map(title=>({title,status:'Unchecked'}))}));render()}if(b.id==='export')download('Suilven-backup.json',blocked?(localStorage.getItem(KEY)||''):JSON.stringify(state,null,2));if(b.dataset.undo){commit(s=>{const c=s.completions.find(c=>c.id===b.dataset.undo);if(c.reversed||s.completions.filter(c=>!c.reversed&&!c.taskID&&!c.libraryID).at(-1)?.id!==c.id)throw Error('Undo the latest completion first');s.parts[0].quantity+=c.used;s.service=c.previous;c.reversed=true});render()}}catch(x){msg(x.message)}});
app.addEventListener('submit',e=>{e.preventDefault();if(!['job','stock','service','fuel'].includes(e.target.id))return;const f=new FormData(e.target);try{if(e.target.id==='job'){const title=f.get('title').trim();if(!title)throw Error('Enter a title');commit(s=>s.jobs.push({id:crypto.randomUUID(),title,notes:f.get('notes'),equipment:f.get('equipment'),status:'Open',date:new Date().toISOString().slice(0,10)}))}if(e.target.id==='stock')commit(s=>{const p=s.parts.find(p=>p.id===selectedPart);p.quantity=optionalNum(f,'quantity');p.minimum=num(f,'minimum');p.location=f.get('location').trim();p.name=f.get('name').trim();p.number=f.get('number').trim();p.category=f.get('category').trim();p.equipmentGroups=f.getAll('equipmentGroups');p.supplier=f.get('supplier');p.aliases=f.get('aliases');if(!p.name)throw Error('Enter a part name');p.verified=p.quantity!==null&&!!p.location;if(p.quantity!==null&&!p.location)throw Error('Enter the current storage location to confirm this stock, or leave quantity blank for an uncounted part')});if(e.target.id==='service'){const hours=num(f,'hours'),used=num(f,'used'),date=f.get('date');if(!Number.isInteger(used))throw Error('Filters used must be a whole number');if(date>new Date().toISOString().slice(0,10))throw Error('Completion cannot be in the future');commit(s=>{if(hours<s.service.lastHours||date<s.service.lastDate)throw Error('Completion precedes the recorded baseline');if(used>0&&(s.parts[0].quantity===null||s.parts[0].quantity<used))throw Error('Confirm sufficient stock in Parts & Spares first');s.completions.push({id:crypto.randomUUID(),date,hours,used,notes:f.get('notes'),previous:structuredClone(s.service),reversed:false});if(used>0)s.parts[0].quantity-=used;s.service.lastHours=hours;s.service.lastDate=date})}if(e.target.id==='fuel'){const p={name:f.get('name'),start:num(f,'start'),end:num(f,'end'),added:num(f,'added'),distance:num(f,'distance'),duration:num(f,'duration')};p.litres=(p.start+p.added-p.end)*3.785411784;if(p.litres<0||p.distance<=0||p.duration<=0)throw Error('Check fuel amounts; distance and duration must be positive');commit(s=>s.passages.push(p))}if(e.target.id==='stock'){partSaved=true;if(e.submitter?.value!=='stay'&&e.target.dataset.saveMode!=='stay'){returnToParts();msg('Part saved on this device');return}}render();msg('Saved on this device')}catch(x){msg(x.message)}});
app.addEventListener('change',async e=>{try{if(e.target.dataset.check!==undefined){commit(s=>s.checks.at(-1).items[Number(e.target.dataset.check)].status=e.target.value);msg('Checklist saved')}if(e.target.id==='restore'&&e.target.files[0]){const next=JSON.parse(await e.target.files[0].text());validate(next);if(confirm('Replace current records? Export a backup first if needed.')){localStorage.setItem(KEY,JSON.stringify(migrate(next)));state=migrate(next);blocked=false;render();msg('Backup restored')}}}catch(x){msg(x.message)}});
function connection(){document.querySelector('#connection').textContent=navigator.onLine?'Online':'Offline'}window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();render();
if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>msg('Offline cache unavailable; keep a backup.'));

function serviceHistoryNotice(t){const hasHours=Number.isFinite(t.lastHours),hasDate=!!t.lastDate;if(!hasHours&&!hasDate)return '<p class="warning"><strong>Service history unknown — inspection required</strong></p><p>Schedule active. No previous service is recorded; next due cannot yet be calculated. Activation is not a completed service.</p>';if((t.intervalHours&&!hasHours)||(t.intervalMonths&&!hasDate))return '<p class="warning"><strong>Service history incomplete — baseline needs checking</strong></p><p>One or more required last-service readings are missing. Any available due estimate is shown below.</p>';return ''}
function nextDate(date,months){const [y,m,d]=date.split('-').map(Number);const dt=new Date(Date.UTC(y,m-1+months,1));dt.setUTCDate(Math.min(d,new Date(Date.UTC(dt.getUTCFullYear(),dt.getUTCMonth()+1,0)).getUTCDate()));return dt.toISOString().slice(0,10)}
function oldPartOptions(){return '<option value="">None</option>'+state.parts.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${esc(p.number)}</option>`).join('')}
function optionalNum(f,k){return f.get(k)===''?null:num(f,k)}
app.addEventListener('input',e=>{if(e.target.id==='part-search'){const pos=e.target.selectionStart;search=e.target.value;render();const input=document.querySelector('#part-search');input.focus();input.setSelectionRange(pos,pos)}});
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-partsback')){returnToParts();return}if(b.dataset.part){rememberPartsPosition();selectedPart=b.dataset.part;partSaved=false;page='part';render();window.scrollTo(0,0)}if(b.hasAttribute('data-newpart')){rememberPartsPosition();partSaved=false;const id=crypto.randomUUID();commit(s=>s.parts.push({id,name:'New part',number:'Unknown',category:'Other',quantity:null,location:'',minimum:1,supplier:'',aliases:'',verified:false}));selectedPart=id;page='part';render();window.scrollTo(0,0)}if(b.dataset.equipment){selectedTask=b.dataset.equipment;page='tasks';render()}if(b.dataset.task){selectedTask=b.dataset.task;page='task';render()}if(b.dataset.taskundo){commit(s=>{const c=s.completions.find(c=>c.id===b.dataset.taskundo);if(c.reversed||s.completions.filter(x=>x.taskID===c.taskID&&!x.reversed).at(-1)?.id!==c.id)throw Error('Undo the latest service for this task first');const t=s.tasks.find(t=>t.id===c.taskID);t.lastHours=c.previous.lastHours;t.lastDate=c.previous.lastDate;if(c.used>0)s.parts.find(p=>p.id===c.part).quantity+=c.used;c.reversed=true});render()}}catch(x){msg(x.message)}});
app.addEventListener('submit',e=>{const f=new FormData(e.target);try{if(e.target.id==='newtask'){const h=optionalNum(f,'intervalHours'),m=optionalNum(f,'intervalMonths');if((h!==null&&h<=0)||(m!==null&&(!Number.isInteger(m)||m<=0))||(!h&&!m))throw Error('Enter a positive hour or month interval');commit(s=>s.tasks.push({id:crypto.randomUUID(),equipment:selectedTask,name:f.get('name').trim(),source:f.get('source'),intervalHours:h,intervalMonths:m,lastHours:optionalNum(f,'lastHours'),lastDate:f.get('lastDate')||null,part:f.get('part')||null}));page='tasks';render();msg('Schedule saved')}if(e.target.id==='task-service'){const hours=optionalNum(f,'hours'),used=num(f,'used'),date=f.get('date');if(date>new Date().toISOString().slice(0,10))throw Error('Completion cannot be in the future');commit(s=>{const t=s.tasks.find(t=>t.id===selectedTask);if(t.intervalHours&&hours===null)throw Error('Enter hours for an hour-based schedule');if((hours!==null&&t.lastHours!==null&&hours<t.lastHours)||(t.lastDate&&date<t.lastDate))throw Error('Completion precedes the last service');const consumedPart=f.get('part')||null;const p=s.parts.find(p=>p.id===consumedPart);if(used>0&&(!p||!p.verified||p.quantity<used))throw Error('Confirm sufficient linked stock first');s.completions.push({id:crypto.randomUUID(),taskID:t.id,date,hours,used,part:consumedPart,notes:f.get('notes'),previous:{lastHours:t.lastHours,lastDate:t.lastDate},reversed:false});if(used>0)p.quantity-=used;if(hours!==null)t.lastHours=hours;t.lastDate=date});render();msg('Service saved')}}catch(x){msg(x.message)}});
app.addEventListener('change',async e=>{if(e.target.id!=='inventory-file'||!e.target.files[0])return;try{const imported=JSON.parse(await e.target.files[0].text());if(imported.format!=='suilven-inventory-1'||!Array.isArray(imported.parts)||imported.parts.length>5000)throw Error('Select the supplied inventory import file');for(const p of imported.parts)if(!p.id||typeof p.name!=='string'||typeof p.number!=='string')throw Error('Invalid inventory entry');let added=0;commit(s=>{for(const p of imported.parts){if(s.parts.some(x=>x.id===p.id))continue;const oil=s.parts.find(x=>x.id==='oil');if(p.number.replace(/\s/g,'')==='RE504836'&&oil){Object.assign(oil,{historicalQuantity:p.historicalQuantity,historicalLocation:p.historicalLocation,source:p.source,importID:p.id});continue}s.parts.push({...p,quantity:null,location:'',minimum:1,verified:false});added++}});page='parts';render();msg(`${added} entries imported locally. Historical locations and quantities need confirmation.`)}catch(x){msg(x.message)}});

function importSchedules(imported){if(imported.format!=='suilven-schedules-1'||!Array.isArray(imported.tasks)||imported.tasks.length>1000)throw Error('Select the supplied engine schedules JSON file');const ids=new Set();for(const t of imported.tasks){if(typeof t.id!=='string'||!t.id||ids.has(t.id)||!['Main engine','Wing engine','Generator','Other equipment'].includes(t.equipment)||typeof t.name!=='string'||typeof t.source!=='string')throw Error('Invalid schedule entry');ids.add(t.id);for(const key of ['intervalHours','intervalMonths','lastHours'])if(t[key]!==null&&(!Number.isFinite(t[key])||t[key]<0))throw Error('Invalid schedule number');if((t.intervalHours!==null&&t.intervalHours<=0)||(t.intervalMonths!==null&&(!Number.isInteger(t.intervalMonths)||t.intervalMonths<=0))||(!t.intervalHours&&!t.intervalMonths))throw Error('Invalid schedule interval');if(t.lastDate!==null&&!/^\d{4}-\d{2}-\d{2}$/.test(t.lastDate))throw Error('Invalid baseline date')}
let added=0;commit(s=>{for(const t of imported.tasks){if(s.scheduleDrafts.some(x=>x.id===t.id)||s.tasks.some(x=>x.importID===t.id))continue;s.scheduleDrafts.push({...t,activated:false});added++}});return added}
app.addEventListener('change',async e=>{if(e.target.id!=='schedule-file'||!e.target.files[0])return;try{const count=importSchedules(JSON.parse(await e.target.files[0].text()));render();msg(`${count} schedules imported for review. Existing records preserved.`)}catch(x){msg(x.message)}});
app.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.hasAttribute('data-reviewback')){returnToScheduleReview();return}if(b?.dataset.draft){reviewReturnPage=page==='schedule-import'?'schedule-import':'boat-equipment';reviewScroll=window.scrollY||0;selectedTask=b.dataset.draft;page='schedule-review';render();window.scrollTo(0,0)}});
app.addEventListener('submit',e=>{if(e.target.id!=='activate-schedule')return;e.preventDefault();try{const f=new FormData(e.target),h=optionalNum(f,'intervalHours'),m=optionalNum(f,'intervalMonths'),lh=optionalNum(f,'lastHours'),ld=f.get('lastDate')||null;if(!f.get('confirmed'))throw Error('Confirm the schedule checks first');if((h!==null&&h<=0)||(m!==null&&(!Number.isInteger(m)||m<=0))||(!h&&!m))throw Error('Enter a positive hour or month interval');if(ld&&ld>new Date().toISOString().slice(0,10))throw Error('Last service cannot be in the future');const basis=f.get('basis').trim();if(!basis)throw Error('Explain the chosen interval');let equipment;commit(s=>{const d=s.scheduleDrafts.find(d=>d.id===selectedTask);if(!d||d.activated)throw Error('Schedule already activated');equipment=d.equipment;s.tasks.push({id:crypto.randomUUID(),importID:d.id,equipment:d.equipment,name:d.name,source:d.source+' · Chosen basis: '+basis,reviewNotes:d.reviewNotes,intervalHours:h,intervalMonths:m,lastHours:lh,lastDate:ld,part:f.get('part')||null});d.activated=true});reviewNotice='✓ Schedule activated. No service recorded or stock deducted.';returnToScheduleReview();msg(reviewNotice)}catch(x){msg(x.message)}});

const equipmentNames=['Main engine','Wing engine','Generator','Other equipment'];
function partGroups(p){if(Array.isArray(p.equipmentGroups))return p.equipmentGroups;const txt=[p.name,p.historicalLocation].join(' ').toLowerCase();const groups=[];if(p.id==='oil'||/\bmain\b|\bm\/e\b/.test(txt))groups.push('Main engine');if(/\bwing\b|\byanmar\b/.test(txt))groups.push('Wing engine');if(/\bgen\b|\bgenerator\b/.test(txt)||p.category==='Generator')groups.push('Generator');if(!groups.length&&p.category&& !['Engine','Generator','Filter','Drivetrain','Other'].includes(p.category))groups.push('Other equipment');return groups}
function filteredParts(equipment,query='',scope='equipment'){return state.parts.filter(p=>(scope==='all'||(scope==='unknown'?partGroups(p).length===0:partGroups(p).includes(equipment)))&&[p.name,p.number,p.aliases,p.supplier].join(' ').toLowerCase().includes(query.toLowerCase()))}
function optionLabel(p){return `${p.name} · ${p.number} · ${p.verified?p.quantity+' onboard':'stock unconfirmed'}${partGroups(p).length?'':' · equipment unassigned'}`}
function partOptions(equipment,query='',scope='all',selected=''){const parts=filteredParts(equipment,query,scope);const retained=state.parts.find(p=>p.id===selected);if(retained&&!parts.some(p=>p.id===selected))parts.unshift(retained);return '<option value="">None / no stock deduction</option>'+parts.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(optionLabel(p))}</option>`).join('')}
function partPicker(equipment,selected=''){return `<fieldset data-partpicker data-equipment="${esc(equipment)}"><legend>Service part · ${esc(equipment)}</legend><label>Show<select data-partscope><option value="equipment">${esc(equipment)} parts</option><option value="unknown">Unassigned equipment</option><option value="all">All stock / miscellaneous</option></select></label><label>Search part name or number<input data-partquery type="search" placeholder="e.g. belt or part number"></label><label>Select the part<select name="part">${partOptions(equipment,'','equipment',selected)}</select></label><p>Groups come from inventory descriptions, not verified fit. Edit a part to correct its equipment group. Shared parts can belong to several engines.</p></fieldset>`}
function refreshPartPicker(target){const box=target.closest('[data-partpicker]');if(!box)return;const select=box.querySelector('[name="part"]');select.innerHTML=partOptions(box.dataset.equipment,box.querySelector('[data-partquery]').value,box.querySelector('[data-partscope]').value,select.value)}
app.addEventListener('input',e=>{if(e.target.hasAttribute('data-partquery'))refreshPartPicker(e.target)});
app.addEventListener('change',e=>{if(e.target.hasAttribute('data-partscope'))refreshPartPicker(e.target)});

function rememberPartsPosition(){partsReturnPage=page==='reorder'?'reorder':'parts';partsScroll=page==='parts'||page==='reorder'?window.scrollY:0}
function returnToParts(){page=partsReturnPage;render();requestAnimationFrame(()=>window.scrollTo(0,partsScroll))}
app.addEventListener('input',e=>{if(e.target.closest?.('#stock')){partSaved=false;const notice=app.querySelector('.save-confirmation');if(notice)notice.remove()}});

app.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.form?.id==='stock')b.form.dataset.saveMode=b.value==='stay'?'stay':'return'});

let manualsDBPromise,manualImportBusy=false;
function manualsDB(){if(!manualsDBPromise)manualsDBPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('suilven-manuals',1);r.onupgradeneeded=()=>r.result.createObjectStore('pdfs',{keyPath:'id'});r.onsuccess=()=>{r.result.onversionchange=()=>{r.result.close();manualsDBPromise=null};resolve(r.result)};r.onerror=()=>{manualsDBPromise=null;reject(r.error)};r.onblocked=()=>{manualsDBPromise=null;reject(Error('Close other Suilven tabs and try again'))}});return manualsDBPromise}
async function manualStore(action,id,record){const db=await manualsDB();return new Promise((resolve,reject)=>{const tx=db.transaction('pdfs',action==='get'?'readonly':'readwrite'),store=tx.objectStore('pdfs');const r=action==='get'?store.get(id):action==='put'?store.put(record):store.delete(id);tx.oncomplete=()=>resolve(r.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('PDF storage aborted'))})}
function manualStatus(message){const el=document.querySelector('#manual-status');if(el)el.textContent=message;else msg(message)}
async function importManualFiles(files,equipment){if(blocked)throw Error('Restore readable records before importing manuals');let added=0;for(const file of files){if(!/\.pdf$/i.test(file.name))throw Error('Select PDF files only');const signature=new TextDecoder().decode(await file.slice(0,5).arrayBuffer());if(signature!=='%PDF-')throw Error(`${file.name} is not a readable PDF`);if(state.manuals.some(m=>m.name===file.name&&m.size===file.size&&m.modified===file.lastModified))continue;manualStatus(`Saving ${file.name} locally…`);const id=crypto.randomUUID(),meta={id,name:file.name,equipment:equipment==='Automatic from filename'?manualEquipment(file.name):equipment,size:file.size,modified:file.lastModified,imported:new Date().toISOString()};await manualStore('put',id,{id,blob:file});try{commit(s=>s.manuals.push(meta))}catch(e){await manualStore('delete',id);throw e}added++}return added}
app.addEventListener('submit',async e=>{if(e.target.id!=='manual-import')return;e.preventDefault();if(manualImportBusy)return;manualImportBusy=true;const button=e.target.querySelector('button');button.disabled=true;try{const files=Array.from(e.target.elements.files.files);if(!files.length)throw Error('Select a PDF from Files first');const added=await importManualFiles(files,e.target.elements.equipment.value);if(page==='manuals'){render();manualStatus(`✓ ${added} manual(s) saved locally. Repeated files skipped. Test opening one while offline.`)}}catch(x){manualStatus(`Import stopped: ${x.message}. Previously saved PDFs are retained.`)}finally{manualImportBusy=false;if(button.isConnected)button.disabled=false}});
app.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.manual){try{const m=state.manuals.find(m=>m.id===b.dataset.manual);manualStatus('Reading local PDF…');const record=await manualStore('get',m.id);if(!record?.blob)throw Error('PDF copy is missing from this browser. Re-import the original from Files; JSON restore does not restore PDFs.');const url=URL.createObjectURL(record.blob);const pdfPage=Number(b.dataset.pdfpage)||1;const pageURL=url+'#page='+pdfPage;const panel=document.createElement('section');panel.innerHTML=`<h2>${esc(m.name)}</h2><p>Reference: PDF page ${pdfPage}. Your iPad viewer may require you to enter that page manually.</p><a target="_blank" rel="noopener" href="${pageURL}">Open full PDF</a> · <a download="${esc(m.name)}" href="${url}">Save PDF to Files</a><button type="button">Close preview</button><iframe title="${esc(m.name)}" src="${pageURL}" style="width:100%;height:65vh;border:0"></iframe>`;panel.querySelector('button').onclick=()=>{panel.remove();URL.revokeObjectURL(url)};app.append(panel);panel.scrollIntoView({block:'start'});manualStatus('✓ Opened from local storage.')}catch(x){manualStatus(x.message)}}if(b.id==='manual-storage'){try{const estimate=await navigator.storage?.estimate?.();const retained=await navigator.storage?.persist?.();document.querySelector('#manual-storage-status').textContent=`${estimate?`Website storage: ${(estimate.usage/1048576).toFixed(1)} MB used; estimated allowance ${(estimate.quota/1073741824).toFixed(1)} GB. `:''}${retained?'Storage retention granted.':'Storage retention is not guaranteed.'} Keep original PDFs in Files.`}catch(x){manualStatus(x.message)}}});

function manualEquipment(name){if(/yanmar|3ym|km3v|km2p/i.test(name))return 'Wing engine';if(/l1066|lugger|john.?deere|1066t/i.test(name))return 'Main engine';if(/843nw|northern.?lights/i.test(name))return 'Generator';if(/maxwell|rocna|anchor/i.test(name))return 'Anchoring & Windlass';if(/trac|stabili/i.test(name))return 'Stabilisers';if(/water.?maker|wmkr|hro|ecosistem|cat pump/i.test(name))return 'Watermaker';if(/victron|multiplus|blue.?sea/i.test(name))return 'Electrical';if(/le[e]?ce|alternator/i.test(name))return 'Alternators';if(/tecma|sealand|toilet/i.test(name))return 'Sanitation';if(/racor/i.test(name))return 'Fuel filtration';if(/crane|davit|rib|tender/i.test(name))return 'Crane & tender';if(/yamaha/i.test(name))return 'Outboard';if(/dometic|air.?cond/i.test(name))return 'Air conditioning';if(/jabsco|shurflo|pump/i.test(name))return 'Pumps & plumbing';if(/n4334/i.test(name))return 'Boat handbook';return 'Other equipment — review grouping'}

function manualGroup(m){return m.groupOverride||(m.equipment&&!m.equipment.startsWith('Other equipment')?m.equipment:manualEquipment(m.name))}
function manualLibrary(){const groups=[...new Set(state.manuals.map(manualGroup))].sort();return `<label>Search saved manuals<input id="manual-search" type="search" placeholder="Name or equipment"></label><p>${state.manuals.length} local catalogue entries</p>${groups.map(g=>`<section data-manualgroup><h2>${esc(g)}</h2>${state.manuals.filter(m=>manualGroup(m)===g).map(m=>`<article data-manualentry data-search="${esc((m.name+' '+g).toLowerCase())}"><h3>${esc(m.name)}</h3><p>${((m.size??0)/1048576).toFixed(1)} MB</p><button data-manual="${esc(m.id)}">Open saved PDF</button><button data-groupmanual="${esc(m.id)}">Change equipment group</button></article>`).join('')}</section>`).join('')}`}
function referenceButton(m,page,label){return `<button type="button" data-manual="${esc(m.id)}" data-pdfpage="${page}">${esc(label)} · PDF page ${page}</button>`}
function serviceReferences(t){const linked=state.boatServiceLibrary.tasks.find(r=>r.id===t.importID);if(linked)return libraryReferenceLinks(linked.references)+(t.equipment==='Main engine'&&/oil|lube/i.test(t.name)&&!/gear/i.test(t.name)?mainOilReferences():'');if(t.equipment==='Main engine'&&/oil|lube/i.test(t.name)&&!/gear/i.test(t.name))return mainOilReferences();let file='',pdf=1;const name=t.name.toLowerCase();if(t.equipment==='Main engine'){file='L1066T Op Manual 2010.pdf';pdf=/oil|air cleaner/.test(name)?15:/valve/.test(name)?16:/fuel filter|damper/.test(name)?17:/leak|turbo/.test(name)?25:13}else if(t.equipment==='Generator'){file='NL843NW2 Ops Manual 2009.pdf';pdf=/oil/.test(name)?12:/air|valve|belt/.test(name)?13:/fuel filter/.test(name)?14:/coolant|impeller|exchanger/.test(name)?18:10}else if(t.equipment==='Wing engine'){file='yanmar_ym_series_operations_manual_v2_21jan09.pdf';pdf=/oil|gear|fuel filter/.test(name)?57:/impeller|coolant|air|exhaust|water/.test(name)?58:59}
// Only oil/air and the visually checked schedule chart pages are direct references.
if(t.equipment==='Main engine'&&!/oil|air cleaner/.test(name))pdf=13;
if(t.equipment==='Generator'&&!/oil/.test(name))pdf=10;
const m=state.manuals.find(m=>m.name.toLowerCase()===file.toLowerCase());return `<section><h2>Manual reference</h2>${m?referenceButton(m,pdf,'Open task reference'):`<p>Matching reference PDF not found: ${esc(file||'No verified reference assigned')}.</p>`}<p>Check the fitted equipment and instructions. Schedule references do not confirm part compatibility.</p></section>`}
function partReferences(p){if(['RE504836','R502513'].includes((p.number||'').replace(/\s/g,'')))return mainOilReferences();const groups=partGroups(p),manuals=state.manuals.filter(m=>groups.includes(manualGroup(m)));return `<section><h2>Related equipment manuals</h2>${manuals.length?manuals.map(m=>referenceButton(m,1,m.name)).join(''):'<p>No matching equipment manual yet. Check the part’s equipment group.</p>'}<p>These are equipment references; this part number has not been verified against each manual.</p></section>`}
app.addEventListener('input',e=>{if(e.target.id==='manual-search'){const q=e.target.value.toLowerCase();for(const entry of app.querySelectorAll('[data-manualentry]'))entry.hidden=!entry.dataset.search.includes(q);for(const group of app.querySelectorAll('[data-manualgroup]'))group.hidden=!Array.from(group.querySelectorAll('[data-manualentry]')).some(x=>!x.hidden)}});
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b?.dataset.groupmanual)return;const m=state.manuals.find(m=>m.id===b.dataset.groupmanual);const box=document.createElement('section');box.innerHTML=`<h2>Group: ${esc(m.name)}</h2><form id="manual-group-edit" data-id="${esc(m.id)}"><label>Equipment group<input name="group" value="${esc(manualGroup(m))}" required></label><button>Save group</button></form>`;app.append(box);box.scrollIntoView({block:'start'})});
app.addEventListener('submit',e=>{if(e.target.id!=='manual-group-edit')return;e.preventDefault();try{const group=new FormData(e.target).get('group').trim();if(!group)throw Error('Enter equipment group');const id=e.target.dataset.id;commit(s=>s.manuals.find(m=>m.id===id).groupOverride=group);render();manualStatus('✓ Equipment group saved. PDF unchanged.')}catch(x){manualStatus(x.message)}});

function mainOilReferences(){const refs=[{name:'L1066T Op Manual 2010.pdf',page:15,label:'Oil / filter change instructions · SP2–SP3'},{name:'L1066T Parts Catalog 2016.pdf',page:35,label:'Exploded oil-filter assembly · 2016 catalogue'},{name:'L1066T Parts Manual 2018.pdf',page:35,label:'Exploded oil-filter assembly · 2018 catalogue'}];return `<section><h2>Oil & filter · instructions and diagrams</h2>${refs.map(r=>{const m=state.manuals.find(m=>m.name.toLowerCase()===r.name.toLowerCase());return m?referenceButton(m,r.page,r.label):`<p>${esc(r.label)}: matching local file not found (${esc(r.name)}).</p>`}).join('')}<p>Procedure: operating manual printed page 13, SP3. Diagram: parts catalogue printed page 1–29, oil filter item 19 (RE504836) and sealing ring item 20 (R502513).</p><p>The exploded view identifies assembly components, not a photographic service sequence. Check that the illustrated L1066T assembly matches your fitted engine before using it.</p></section>`}

let boatEquipment='',boatTaskID='',reviewReturnPage='schedule-import',reviewScroll=0,reviewNotice='';
function boatTaskCard(t){return `<article><h2>${esc(t.name)}</h2><p>${esc(t.equipment)} · ${esc(t.trigger||t.intervalBasis)}</p><button data-boat-task="${esc(t.id)}">Instructions / references / record</button></article>`}
function libraryReferenceLinks(refs=[]){return `<section><h2>Manual pathways</h2>${refs.map(r=>{const normalize=n=>n.toLowerCase().replace(/\s+/g,' ').trim();const m=state.manuals.find(m=>normalize(m.name)===normalize(r.filename));return m?referenceButton(m,r.page,r.label):`<p>Local PDF not found: ${esc(r.filename)} · PDF page ${r.page}. ${esc(r.label)}</p>`}).join('')}<p>PDF page numbers include covers. The iPad viewer may need manual page selection. References labelled “page mapping pending” open the manual start, not a verified procedure.</p></section>`}
function importBoatServices(file){if(file.format!=='suilven-boat-service-1'||!Array.isArray(file.tasks)||!Array.isArray(file.sections)||file.tasks.length>2000)throw Error('Select the supplied whole-boat service library');if(file.equipmentImages){for(const image of Object.values(file.equipmentImages))if(typeof image.data!=='string'||!/^data:image\/(png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(image.data)||image.data.length>600000||typeof image.alt!=='string'||typeof image.caption!=='string')throw Error('Invalid equipment picture')}const ids=new Set();for(const t of file.tasks){if(typeof t.id!=='string'||ids.has(t.id)||typeof t.name!=='string'||typeof t.equipment!=='string'||!Array.isArray(t.references))throw Error('Invalid service entry');ids.add(t.id);for(const r of t.references)if(typeof r.filename!=='string'||!Number.isInteger(r.page)||r.page<1)throw Error('Invalid PDF reference');for(const k of ['intervalHours','intervalMonths'])if(t[k]!==null&&(!Number.isFinite(t[k])||t[k]<=0))throw Error('Invalid interval');if(t.intervalMonths!==null&&!Number.isInteger(t.intervalMonths))throw Error('Invalid month interval')}
commit(s=>{const pictures=file.equipmentImages||s.boatServiceLibrary.equipmentImages;s.boatServiceLibrary=structuredClone(file);if(pictures)s.boatServiceLibrary.equipmentImages=structuredClone(pictures);for(const t of file.tasks)if((t.intervalHours||t.intervalMonths)&&!s.scheduleDrafts.some(d=>d.id===t.id)&&!s.tasks.some(a=>a.importID===t.id))s.scheduleDrafts.push({...t,activated:false})});return file.tasks.length}
function boatImportStatus(text){const status=document.querySelector('#boat-import-status');if(status){status.textContent=text;status.className='save-confirmation';status.scrollIntoView({block:'nearest'})}msg(text)}
app.addEventListener('change',e=>{if(e.target.id==='boat-service-file'){const file=e.target.files?.[0];boatImportStatus(file?'Selected '+file.name+'. Tap Import selected library to save it.':'No file selected.')}});
app.addEventListener('submit',async e=>{if(e.target.id!=='boat-service-import')return;e.preventDefault();const input=e.target.elements.library,file=input.files?.[0],button=e.target.querySelector('button');if(!file){boatImportStatus('Select the downloaded JSON library from Files first.');return}button.disabled=true;boatImportStatus('Reading '+file.name+'…');try{const text=await file.text();let parsed;try{parsed=JSON.parse(text.replace(/^\uFEFF/,''))}catch{throw Error('This file is not valid JSON. Select Suilven-Whole-Boat-Service-Library.json.')}const count=importBoatServices(parsed);render();boatImportStatus('✓ '+count+' service references saved on this device. Existing services and stock preserved.')}catch(x){boatImportStatus('Import failed: '+(x.name==='QuotaExceededError'?'Device record storage is full. Export a backup before making changes.':x.message)+'. Existing records remain unchanged.')}finally{if(button.isConnected)button.disabled=false}});
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.boatEquipment){boatEquipment=b.dataset.boatEquipment;page='boat-equipment';render();window.scrollTo(0,0)}if(b.dataset.boatTask){boatTaskID=b.dataset.boatTask;page='boat-task';render();window.scrollTo(0,0)}});
app.addEventListener('input',e=>{if(e.target.id==='boat-task-search'){const q=e.target.value.trim().toLowerCase();document.querySelector('#boat-task-results').innerHTML=q?state.boatServiceLibrary.tasks.filter(t=>(t.name+' '+t.equipment+' '+t.trigger).toLowerCase().includes(q)).map(boatTaskCard).join(''):''}});
app.addEventListener('submit',e=>{if(e.target.id!=='boat-inspection')return;e.preventDefault();try{const f=new FormData(e.target),date=f.get('date'),notes=f.get('notes').trim(),id=e.target.dataset.id;if(!notes||!date||date>new Date().toISOString().slice(0,10))throw Error('Enter completed work notes and a valid past or current date');commit(s=>s.completions.push({id:crypto.randomUUID(),libraryID:id,date,notes,used:0,reversed:false}));render();msg('Inspection recorded. No schedule reset or stock deduction.')}catch(x){msg(x.message)}});

function returnToScheduleReview(){page=reviewReturnPage;render();requestAnimationFrame(()=>window.scrollTo(0,reviewScroll))}
function localToday(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function scheduleStatus(t,today=localToday(),readings=state.meterReadings||{}){const reasons=[],missing=[];let due=false,overdue=false;const nextHours=t.intervalHours&&Number.isFinite(t.lastHours)?t.lastHours+t.intervalHours:null,nextDay=t.intervalMonths&&t.lastDate?nextDate(t.lastDate,t.intervalMonths):null;const meter=readings[t.equipment];if(nextDay){if(today>nextDay){overdue=true;reasons.push('Calendar overdue · due '+nextDay)}else if(today===nextDay){due=true;reasons.push('Due today')}else reasons.push('Next date '+nextDay)}else if(t.intervalMonths)missing.push('last-service date');if(nextHours!==null){if(Number.isFinite(meter?.hours)){if(meter.hours<t.lastHours)missing.push('meter below service baseline');else if(meter.hours>nextHours){overdue=true;reasons.push('Hour interval overdue · due '+nextHours+' h')}else if(meter.hours===nextHours){due=true;reasons.push('Due at current reading · '+nextHours+' h')}else reasons.push((nextHours-meter.hours).toFixed(1)+' h remaining');reasons.push('Reading '+meter.hours+' h · '+meter.date)}else missing.push('current equipment hours');reasons.push('Next at '+nextHours+' h')}else if(t.intervalHours)missing.push('last-service hours');const unknown=!Number.isFinite(t.lastHours)&&!t.lastDate;const status=overdue?'Overdue':due?'Due now':unknown?'Service history unknown — inspection required':missing.length?'Needs checking':'Within recorded intervals';return {status,reasons:reasons.concat(missing.length?['Missing: '+missing.join(', ')]:[]),attention:overdue||due||unknown||!!missing.length}}
function scheduleStatusHTML(t){const s=scheduleStatus(t);return `<p class="${s.status==='Overdue'?'status-overdue':s.status==='Needs checking'?'status-check':s.attention?'warning':'save-confirmation'}"><strong>${esc(s.status)}</strong></p><p>${esc(s.reasons.join(' · '))}</p>`}
function servicingAttention(){const main={id:'main-oil',name:'Main engine oil and filter',equipment:'Main engine',intervalHours:state.service.interval,intervalMonths:null,lastHours:state.service.lastHours,lastDate:state.service.lastDate};const tasks=[main,...state.tasks];const cards=tasks.map(t=>({t,s:scheduleStatus(t)})).filter(x=>x.s.attention).sort((a,b)=>(a.s.status==='Overdue'?0:1)-(b.s.status==='Overdue'?0:1));const events=state.boatServiceLibrary.tasks.filter(t=>t.id!=='n43-main-oil-confirmed'&&!t.intervalHours&&!t.intervalMonths&&!state.completions.some(c=>c.libraryID===t.id&&!c.reversed));return `<h1>Servicing · Needs attention</h1><button data-page="service">← Servicing</button><p>Overdue dates are calculated from the last actual service. Hour status uses your latest entered meter reading, not live engine data. Unknown history is an inspection requirement, not proof that work is overdue.</p><details><summary>Update equipment hours</summary><form id="meter-readings"><label>Equipment<select name="equipment">${[...new Set(['Main engine','Wing engine','Generator',...state.tasks.filter(t=>t.intervalHours).map(t=>t.equipment)])].map(e=>`<option>${esc(e)}</option>`).join('')}</select></label>${field('hours','Current meter hours','number')}${field('date','Reading date','date',localToday())}<button>Save reading · no service recorded</button></form></details><h2>${cards.length} schedules need attention</h2>${cards.map(({t,s})=>`<article><h2>${esc(t.equipment)} · ${esc(t.name)}</h2>${scheduleStatusHTML(t)}<p>Last service: ${esc(t.lastDate||'Date unknown')} · ${t.lastHours??'Hours unknown'} h</p><button ${t.id==='main-oil'?'data-page="main"':`data-task="${esc(t.id)}"`}>Open / record completed work</button></article>`).join('')}${!cards.length?'<p>No schedule warnings from the available records.</p>':''}<h2>${events.length} checks without an inspection record</h2><p>These are operating, condition or event checks. Inspect when applicable; a dated inspection does not reset a separate service schedule.</p>${events.map(t=>`<article><h2>${esc(t.equipment)} · ${esc(t.name)}</h2><p class="warning">No inspection record — review required</p><p>${esc(t.trigger)}</p><button data-boat-task="${esc(t.id)}">Open instructions / record inspection</button></article>`).join('')}`}
app.addEventListener('submit',e=>{if(e.target.id!=='meter-readings')return;e.preventDefault();try{const f=new FormData(e.target),hours=num(f,'hours'),date=f.get('date'),equipment=f.get('equipment');if(!date||date>localToday())throw Error('Enter a past or current reading date');commit(s=>{s.meterReadings??={};const old=s.meterReadings[equipment];if(old&&(date<old.date||hours<old.hours))throw Error('Reading precedes the latest stored reading');s.meterReadings[equipment]={hours,date}});render();msg('Meter reading saved. No service recorded.')}catch(x){msg(x.message)}});
function upcomingMaintenanceData(today=localToday()){const tasks=[{id:'main-oil',name:'Oil and filter',equipment:'Main engine',intervalHours:state.service.interval,intervalMonths:null,lastHours:state.service.lastHours,lastDate:state.service.lastDate},...state.tasks];const dates=[],hours=[];let unavailable=0,overdue=0;for(const t of tasks){const status=scheduleStatus(t,today);if(status.status==='Overdue'){overdue++;continue}let included=false;if(t.intervalMonths&&t.lastDate){const date=nextDate(t.lastDate,t.intervalMonths);if(date>=today){dates.push({t,date});included=true}}if(t.intervalHours&&Number.isFinite(t.lastHours)){const due=t.lastHours+t.intervalHours,meter=state.meterReadings?.[t.equipment],remaining=Number.isFinite(meter?.hours)&&meter.hours>=t.lastHours?due-meter.hours:null;if(remaining===null||remaining>=0){hours.push({t,due,remaining,meter});included=true}}if(!included)unavailable++}dates.sort((a,b)=>a.date.localeCompare(b.date)||a.t.equipment.localeCompare(b.t.equipment)||a.t.name.localeCompare(b.t.name));hours.sort((a,b)=>a.t.equipment.localeCompare(b.t.equipment)||a.due-b.due||a.t.name.localeCompare(b.t.name));return {dates,hours,unavailable,overdue}}
function upcomingMaintenance(){const d=upcomingMaintenanceData();const open=t=>`<button ${t.id==='main-oil'?'data-page="main"':`data-task="${esc(t.id)}"`}>Open / record completed work</button>`;return `<h1>Upcoming maintenance</h1><button data-page="service">← Servicing</button><p>Calculated from recorded service baselines and chosen intervals. Activation alone does not record work. Where both hours and dates apply, whichever comes first determines when the task is due.</p><button data-page="attention">Needs attention / update equipment hours</button><h2>By date · soonest first</h2>${d.dates.length?d.dates.map(({t,date})=>`<article><h2>${esc(t.equipment)} · ${esc(t.name)}</h2><p class="save-confirmation"><strong>${date===localToday()?'Due today':'Due '+esc(date)}</strong></p><p>Last recorded service ${esc(t.lastDate)} · interval ${t.intervalMonths} months</p>${scheduleStatusHTML(t)}${open(t)}</article>`).join(''):'<p>No upcoming calendar dates can be calculated from the available records.</p>'}<h2>By equipment hours · next due first for each equipment</h2><p>Each equipment has its own meter. Remaining hours use the latest saved reading; they are not a predicted calendar date.</p>${d.hours.length?d.hours.map(({t,due,remaining,meter})=>`<article><h2>${esc(t.equipment)} · ${esc(t.name)}</h2><p class="save-confirmation"><strong>Due at ${due} h${remaining!==null?' · '+remaining.toFixed(1)+' h remaining':''}</strong></p><p>${remaining===null?'Current meter reading required to calculate remaining hours.':'Reading '+meter.hours+' h · '+esc(meter.date)}</p><p>Last service ${t.lastHours} h · interval ${t.intervalHours} h</p>${open(t)}</article>`).join(''):'<p>No upcoming hour thresholds can be calculated from the available records.</p>'}<p>${d.overdue} overdue schedule(s) and ${d.unavailable} schedule(s) without a calculable upcoming trigger are available in Needs attention.</p>`}
function reportTable(headers,rows){return rows.length?`<div class="report-table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<p>None recorded.</p>'}
function vesselReport(){const tasks=[{id:'main-oil',equipment:'Main engine',name:'Oil and filter',intervalHours:state.service.interval,intervalMonths:null,lastHours:state.service.lastHours,lastDate:state.service.lastDate},...state.tasks];const upcoming=upcomingMaintenanceData();const attention=tasks.map(t=>({t,status:scheduleStatus(t)})).filter(x=>x.status.attention);const history=state.completions.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(c=>{const task=c.taskID?state.tasks.find(t=>t.id===c.taskID):c.libraryID?state.boatServiceLibrary.tasks.find(t=>t.id===c.libraryID):{equipment:'Main engine',name:'Oil and filter'};const part=state.parts.find(p=>p.id===(c.part||(!c.taskID&&!c.libraryID?'oil':'')));return [c.date,task?.equipment||'Equipment record unavailable',task?.name||'Task record unavailable',c.hours??'Not recorded',c.reversed?'Reversed':c.libraryID?'Inspection':'Completed service',c.used?`${c.used} × ${part?.name||'Part unavailable'} · ${part?.number||''}`:'None',c.notes||'']});return `<div id="vessel-report"><h1>SUILVEN</h1><p class="report-subtitle">Nordhavn N43 · Vessel maintenance report</p><p>Generated ${esc(new Date().toLocaleString())} · ${tasks.length} active schedules · ${state.parts.length} inventory entries · ${state.completions.filter(c=>!c.reversed).length} service / inspection records</p><p>Report of records stored on this device. Schedule activation is not evidence of completed work. Unverified stock and historical locations are identified separately. This readable report does not replace the restorable JSON backup; PDF manuals are not included.</p><h2>Equipment readings</h2>${reportTable(['Equipment','Latest entered hours','Reading date'],Object.entries(state.meterReadings||{}).map(([equipment,r])=>[equipment,r.hours,r.date]))}<p>Earlier owner readings, dates unconfirmed: main engine 3,139.7 h; generator 3,247.9 h. These are not used as current readings for overdue calculations.</p><h2>Servicing · needs attention</h2>${reportTable(['Equipment / task','Status','Details'],attention.map(({t,status})=>[t.equipment+' · '+t.name,status.status,status.reasons.join('; ')]))}<h2>Upcoming maintenance · calendar</h2>${reportTable(['Due date','Equipment','Task'],upcoming.dates.map(({t,date})=>[date,t.equipment,t.name]))}<h2>Upcoming maintenance · equipment hours</h2>${reportTable(['Equipment','Task','Due hours','Hours remaining','Reading date'],upcoming.hours.map(({t,due,remaining,meter})=>[t.equipment,t.name,due,remaining===null?'Reading required':remaining.toFixed(1),meter?.date||'Unknown']))}<h2>Active service schedules and baselines</h2>${reportTable(['Equipment','Task','Interval','Last service date','Last service hours'],tasks.map(t=>[t.equipment,t.name,[t.intervalHours?`${t.intervalHours} hours`:'',t.intervalMonths?`${t.intervalMonths} months`:''].filter(Boolean).join(' or '),t.lastDate||'Unknown',t.lastHours??'Unknown']))}<h2>Service and inspection history</h2>${reportTable(['Date','Equipment','Work','Hours','Record state','Parts used','Notes'],history)}<h2>Checks without an inspection record</h2>${reportTable(['Equipment','Task','When applicable'],state.boatServiceLibrary.tasks.filter(t=>t.id!=='n43-main-oil-confirmed'&&!t.intervalHours&&!t.intervalMonths&&!state.completions.some(c=>c.libraryID===t.id&&!c.reversed)).map(t=>[t.equipment,t.name,t.trigger||'Condition / event']))}<h2>Problems and jobs</h2>${reportTable(['Created','Equipment','Job','Status','Notes'],state.jobs.map(j=>[j.date,j.equipment,j.title,j.status,j.notes]))}<h2>Inventory and spares</h2>${reportTable(['Part','Part number','Current quantity','Current location','Reorder at','Supplier / alternatives','Historical location · unverified'],state.parts.map(p=>[p.name,p.number,p.verified?p.quantity:'Unconfirmed',p.location||'Unconfirmed',p.minimum,[p.supplier,p.aliases].filter(Boolean).join(' · '),p.historicalLocation||'Not recorded']))}<h2>Reorder list · confirmed stock</h2>${reportTable(['Part','Number','Onboard','Threshold'],state.parts.filter(p=>p.verified&&p.quantity<=p.minimum).map(p=>[p.name,p.number,p.quantity,p.minimum]))}<h2>Passages and fuel</h2>${reportTable(['Passage','Distance · NM','Duration · hours','Total litres used','L/h','L/NM'],state.passages.map(p=>[p.name,p.distance,p.duration,p.litres.toFixed(1),(p.litres/p.duration).toFixed(2),(p.litres/p.distance).toFixed(2)]))}<p>Fuel use is combined main engine and generator consumption from the main tanks. Wing engine uses its separate tank.</p><h2>Pre-departure checklists</h2>${reportTable(['Started','Item','Status'],state.checks.flatMap(c=>c.items.map(i=>[c.date,i.title,i.status])))}<h2>Manual catalogue · file contents excluded</h2>${reportTable(['Filename','Equipment group'],state.manuals.map(m=>[m.name,manualGroup(m)]))}</div>`}
const reportStyles=`body{font:14px system-ui,sans-serif;color:#14232c;background:white;margin:24px}h1{font-size:32px}h2{font-size:21px;margin-top:30px}p{line-height:1.5}table{border-collapse:collapse;width:100%;font-size:12px}th,td{padding:8px;border:1px solid #ccd5db;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#e8eff3}thead{display:table-header-group}tr{break-inside:avoid}h2{break-after:avoid}@page{size:A4 landscape;margin:12mm}`;
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='print-report')window.print();if(b.id==='download-report')download('Suilven-Vessel-Report-'+localToday()+'.html','<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Suilven vessel report</title><style>'+reportStyles+'</style></head><body>'+vesselReport()+'</body></html>','text/html')});
function serviceArtwork(equipment){if(equipment==='Other equipment')return '<img src="equipment-systems.svg" alt="Windlass, stabiliser fin and water pump illustration">';const image=state.boatServiceLibrary.equipmentImages?.[equipment];return image?`<img src="${esc(image.data)}" alt="${esc(image.alt)}"><small>${esc(image.caption)}</small>`:`<svg viewBox="0 0 120 90" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="4"><rect x="20" y="28" width="80" height="44" rx="8"/><path d="M35 28V18h30v10M15 45h10M95 45h10M30 77h60"/><circle cx="45" cy="50" r="9"/><path d="M65 42h22M65 52h22M65 62h14"/></g></svg>`}
function servicingHome(){const card=(equipment,label,subtitle,route)=>`<button class="equipment-card" ${route}><div class="equipment-picture">${serviceArtwork(equipment)}</div><div class="equipment-copy"><span>${label}</span><p>${subtitle}</p><small>Open servicing →</small></div></button>`;return `<div class="service-heading"><p class="eyebrow">SUILVEN · MAINTENANCE</p><h1>Servicing</h1><p>See what needs attention, plan the next service, or open an equipment schedule.</p></div><div class="maintenance-actions"><button data-page="attention"><span>Needs attention</span><p>Overdue work, missing history and inspections</p></button><button data-page="upcoming"><span>Upcoming maintenance</span><p>Next jobs by date and equipment hours</p></button></div><h2 class="service-section-title">Equipment</h2><div class="equipment-grid">${card('Main engine','Main engine','Lugger · oil, filters and engine schedules','data-equipment="Main engine"')}${card('Wing engine','Wing engine','Yanmar · auxiliary propulsion','data-equipment="Wing engine"')}${card('Generator','Generator','Northern Lights · onboard power','data-equipment="Generator"')}${card('Other equipment','Other equipment','Windlass, stabilisers, pumps and vessel systems','data-page="boat-services"')}</div><div class="service-quick"><button data-page="main">Main engine · oil & filter record</button><button data-equipment="Other equipment">Other owner-added schedules</button></div><h2 class="service-section-title">Manuals & schedule library</h2><div class="service-library-grid"><button data-page="boat-services"><span>Whole-boat service library</span><p>Instructions, manual references and all equipment</p></button><button data-page="schedule-import"><span>Review schedules</span><p>Import, check and activate service intervals</p></button></div><p class="muted">Service dates and hours use the recorded baseline. Activating a schedule does not record completed work.</p>`}

function lastRecordedEngineHours(equipment){const earlier={'Main engine':{hours:3139.7,date:null,label:'Owner reading'},'Wing engine':{hours:83,date:'2025-10-07',label:'Last service record'},'Generator':{hours:3247.9,date:null,label:'Owner reading'}};const candidates=[earlier[equipment]],meter=state.meterReadings?.[equipment];if(Number.isFinite(meter?.hours))candidates.push({...meter,label:'Meter reading'});for(const c of state.completions){if(c.reversed||c.libraryID||!Number.isFinite(c.hours))continue;const engine=c.taskID?state.tasks.find(t=>t.id===c.taskID)?.equipment:'Main engine';if(engine===equipment)candidates.push({hours:c.hours,date:c.date,label:'Service record'})}return candidates.filter(Boolean).sort((a,b)=>b.hours-a.hours||String(b.date||'').localeCompare(String(a.date||'')))[0]}
function renderEngineHours(){const target=document.querySelector('#engine-hours');if(!target)return;target.innerHTML=['Main engine','Wing engine','Generator'].map(equipment=>{const record=lastRecordedEngineHours(equipment);return `<div class="engine-hours-card"><span>${esc(equipment)}</span><b>${esc(record.hours.toLocaleString('en-GB',{maximumFractionDigits:1}))}<em> h</em></b><small>${esc(record.label)} · ${esc(record.date||'date unconfirmed')}</small></div>`}).join('')}
